for i, lang in enumerate(('vi', 'en')):
    data = {'@@locale': lang}
    for key, values in pairs.items():
        data[key] = values[i]
        data['@'+key] = {'description': 'Isolated care coordination design prototype; '+key}
    (root/'l10n'/f'preview_{lang}.arb').write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n')
# A small generated catalogue for this isolated, fixed-fixture prototype only.
lines = ['// Generated by make_strings.py from the prototype ARB catalogues.', 'const previewCopy = <String, Map<String, String>>{']
for lang in ('vi', 'en'):
    data=json.loads((root/'l10n'/f'preview_{lang}.arb').read_text())
    lines.append(f"  '{lang}': {{")
    for k,v in data.items():
        if not k.startswith('@'):
            lines.append('    '+json.dumps(k)+': '+json.dumps(v,ensure_ascii=False)+',')
    lines.append('  },')
lines.append('};')
(root/'preview_copy.g.dart').write_text('\n'.join(lines)+'\n')
